<?php $page_title='Products'; require 'includes/header.php';
$q=trim($_GET['q']??'');$filter=$_GET['status']??'';$sql="SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id";$where=[];$params=[];if($q!==''){$where[]="(p.name LIKE ? OR p.slug LIKE ? OR p.seller_name LIKE ?)";$like='%'.$q.'%';$params=array_merge($params,[$like,$like,$like]);}if(in_array($filter,['pending','approved','rejected'],true)){$where[]="p.status=?";$params[]=$filter;}if($where){$sql.=" WHERE ".implode(' AND ',$where);}$sql.=" ORDER BY (p.status='pending') DESC, p.id DESC";$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();
?><div class="actions" style="margin-bottom:16px"><a class="btn" href="product_edit.php">+ Add product</a> <a class="btn" href="products_bulk.php">📤 Bulk upload (CSV)</a> <a class="btn" href="products.php?status=pending">Pending only</a> <a class="btn" href="products.php">All</a><form method="get"><input class="search" name="q" placeholder="Search products..." value="<?=admin_h($q)?>"></form></div><div class="table-wrap"><table class="table"><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Seller</th><th>Status</th><th>Flash</th><th>Actions</th></tr><?php foreach($rows as $p):?><tr><td><?php if(!empty($p['image'])):?><img class="thumb" src="../<?=admin_h($p['image'])?>" alt=""><?php else:?><?=admin_h($p['emoji'])?><?php endif;?> <b><?=admin_h($p['name'])?></b></td><td><?=admin_h($p['category'])?></td><td><?=CURRENCY.number_format($p['price'],2)?></td><td><?=intval($p['stock'])?></td><td><?=admin_h($p['seller_name'])?></td><td><?php $st=$p['status']??'approved';$color=$st==='approved'?'green':($st==='pending'?'orange':'red');?><span style="color:<?=$color?>;font-weight:700;text-transform:capitalize;"><?=admin_h($st)?></span></td><td><?=!empty($p['is_flash_deal'])?'Yes':'No'?></td><td><?php if(($p['status']??'')==='pending'):?><a class="btn" style="background:#2e7d32" href="product_approve.php?id=<?=intval($p['id'])?>&action=approve" onclick="return confirm('Approve this product?')">Approve</a> <a class="btn red" href="product_approve.php?id=<?=intval($p['id'])?>&action=reject" onclick="return confirm('Reject this product?')">Reject</a> <?php endif;?><a class="btn" href="product_edit.php?id=<?=intval($p['id'])?>">Edit</a> <?php if(($p['status']??'')==='hidden'):?><a class="btn" href="product_unhide.php?id=<?=intval($p['id'])?>">Unhide</a><?php else:?><a class="btn" href="product_hide.php?id=<?=intval($p['id'])?>" onclick="return confirm('Hide this product from the storefront?')">Hide</a><?php endif;?> <a class="btn red" href="product_delete.php?id=<?=intval($p['id'])?>" onclick="return confirm('Delete this product?')">Delete</a></td></tr><?php endforeach;?></table></div><?php require 'includes/footer.php';
